import { and, eq, isNull, or } from \"drizzle-orm\";
import { getDb, members, organizations, ownershipHandovers } from \"@/server/db\";
import { newId } from \"@/lib/id\";
import { OwnershipHandoverError } from \"@/lib/errors\";
import { PermissionDeniedError } from \"@/lib/permissions\";
import { toIsoTimestamp } from \"@/types/common\";
import { NotFoundError } from \"@/server/services/_support\";
import { toMember, toOrganization } from \"./_mappers\";
import type { Actor } from \"@/types/member\";
import type { OrgId, UserId } from \"@/types/common\";
import type { OwnershipHandover } from \"@/types/organization\";

function map(row: typeof ownershipHandovers."'$inferSelect): OwnershipHandover {
  return { ...row, orgId: row.orgId as OrgId, fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId, createdAt: toIsoTimestamp(row.createdAt),
    expiresAt: toIsoTimestamp(row.expiresAt),
    resolvedAt: row.resolvedAt === null ? null : toIsoTimestamp(row.resolvedAt) };
}

export function assertRecordedOwner(actor: Actor, orgId: OrgId): void {
  const org = getDb().select().from(organizations).where(eq(organizations.id, orgId)).get();
  if (!org) throw new NotFoundError("Organization", orgId);
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:update", {
      action: "org:update", resourceKind: "organization", allowed: false, reason: "denied_by_role",
    });
  }
}

function pending(orgId: OrgId) {
  return getDb().select().from(ownershipHandovers)
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
}

export function getPending(orgId: OrgId): OwnershipHandover | null {
  const row = pending(orgId);
  return row && Date.now() < Date.parse(row.expiresAt) ? map(row) : null;
}

export function initiate(actor: Actor, orgId: OrgId, toUserId: UserId): OwnershipHandover {
  return getDb().transaction((tx) => {
    assertRecordedOwner(actor, orgId);
    if (actor.userId === toUserId) throw new OwnershipHandoverError("self");
    const target = tx.select().from(members).where(and(eq(members.orgId, orgId),
      eq(members.userId, toUserId), eq(members.status, "active"), isNull(members.archivedAt))).get();
    if (!target) throw new NotFoundError("Member", toUserId);
    const now = new Date();
    const stamp = toIsoTimestamp(now);
    const previous = pending(orgId);
    if (previous) {
      if (now.getTime() < Date.parse(previous.expiresAt)) throw new OwnershipHandoverError("pending_exists");
      tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: previous.expiresAt })
        .where(eq(ownershipHandovers.id, previous.id)).run();
    }
    return map(tx.insert(ownershipHandovers).values({ id: newId(), orgId,
      fromUserId: actor.userId, toUserId, status: "pending", createdAt: stamp,
      expiresAt: toIsoTimestamp(new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000)), resolvedAt: null,
    }).returning().get());
  });
}

export function resolve(actor: Actor, orgId: OrgId, status: "accepted" | "declined" | "canceled") {
  return getDb().transaction((tx) => {
    if (status === "canceled") assertRecordedOwner(actor, orgId);
    const row = pending(orgId);
    if (!row || (status !== "canceled" && row.toUserId !== actor.userId)) {
      throw new OwnershipHandoverError("nothing_pending");
    }
    const now = new Date();
    if (now.getTime() >= Date.parse(row.expiresAt)) {
      throw new OwnershipHandoverError(status === "canceled" ? "nothing_pending" : "expired");
    }
    const stamp = toIsoTimestamp(now);
    const changes: { memberId: ReturnType<typeof toMember>["id"]; from: ReturnType<typeof toMember>["role"]; to: "owner" | "admin" }[] = [];
    let organization;
    if (status === "accepted") {
      const live = (userId: string) => tx.select().from(members).where(and(eq(members.orgId, orgId),
        eq(members.userId, userId), eq(members.status, "active"), isNull(members.archivedAt))).get();
      const target = live(row.toUserId);
      const source = live(row.fromUserId);
      if (!target || !source) throw new OwnershipHandoverError("nothing_pending");
      if (target.role !== "owner") {
        tx.update(members).set({ role: "owner", updatedAt: stamp }).where(eq(members.id, target.id)).run();
        changes.push({ memberId: toMember(target).id, from: target.role, to: "owner" });
      }
      organization = toOrganization(tx.update(organizations).set({ ownerId: row.toUserId, updatedAt: stamp })
        .where(eq(organizations.id, orgId)).returning().get());
      if (source.role === "owner") {
        tx.update(members).set({ role: "admin", updatedAt: stamp }).where(eq(members.id, source.id)).run();
        changes.push({ memberId: toMember(source).id, from: "owner", to: "admin" });
      }
    }
    const handover = map(tx.update(ownershipHandovers).set({ status, resolvedAt: stamp })
      .where(eq(ownershipHandovers.id, row.id)).returning().get());
    return { handover, organization, changes };
  });
}

export function cancelForMember(orgId: OrgId, userId: UserId): void {
  const row = pending(orgId);
  if (!row || (row.fromUserId !== userId && row.toUserId !== userId)) return;
  const expired = Date.now() >= Date.parse(row.expiresAt);
  getDb().update(ownershipHandovers).set({ status: expired ? "expired" : "canceled",
    resolvedAt: expired ? row.expiresAt : toIsoTimestamp(new Date()) })
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"),
      or(eq(ownershipHandovers.fromUserId, userId), eq(ownershipHandovers.toUserId, userId)))).run();
}
